import React from 'react';
import './Projects.css';

const PROJECTS = [
  {
    title: 'EduTrack LMS',
    desc: 'A learning management system with real-time progress tracking, quizzes, and instructor dashboards built with React and Node.js.',
    tags: ['React', 'Node.js', 'PostgreSQL'],
    href: '#',
    bg: '#f5f5f5',
  },
  {
    title: 'ShopSwift',
    desc: 'A headless e-commerce platform with Stripe payments, inventory management, and a blazing-fast storefront using Next.js.',
    tags: ['Next.js', 'Stripe', 'Prisma'],
    href: '#',
    bg: '#000',
    light: true,
  },
  {
    title: 'TaskBoard Pro',
    desc: 'A Kanban-style project management tool with real-time collaboration, drag-and-drop, and team notifications.',
    tags: ['React', 'Socket.io', 'MongoDB'],
    href: '#',
    bg: '#f5f5f5',
  },
];

export default function Projects() {
  return (
    <section className="py-section" id="projects">
      <div className="container">
        <h2 className="font-display text-3xl font-semibold lg:text-4xl">Featured Projects</h2>
        <p className="text-xl lg:text-2xl mt-2 text-gray-600">
          A selection of real-world products designed, built, and shipped — each solving a concrete problem.
        </p>
      </div>

      <div className="overflow-auto mt-8">
        <div className="container-start">
          <div className="projects-grid flex flex-nowrap gap-4 lg:grid lg:grid-cols-3">
            {PROJECTS.map((proj) => (
              <a
                key={proj.title}
                href={proj.href}
                className="project-card group border w-80 flex-none lg:w-auto flex flex-col"
              >
                {/* Visual area */}
                <div className="project-card__visual flex-none" style={{ background: proj.bg }}>
                  <div className="aspect-4-3 flex items-center justify-center p-8" style={{ minHeight: '200px' }}>
                    <span className={`font-mono text-xs uppercase tracking-widest ${proj.light ? 'text-gray-500' : 'text-gray-400'}`}>
                      {proj.title}
                    </span>
                  </div>
                </div>

                {/* Content */}
                <div className="border-t p-8 flex-1 flex flex-col">
                  <h3 className="font-display text-xl lg:text-2xl font-medium">{proj.title}</h3>
                  <p className="text-lg mt-2 text-gray-600 flex-1">{proj.desc}</p>
                  <div className="project-card__tags mt-4 flex flex-wrap gap-2">
                    {proj.tags.map((tag) => (
                      <span key={tag} className="tag font-mono text-xs uppercase px-2 py-1 border border-gray-300 text-gray-500">
                        {tag}
                      </span>
                    ))}
                  </div>
                </div>
              </a>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
